$editId=(int)($_GET['edit']??0);$edit=null;if($editId){$stmt=mysqli_prepare($conn,'SELECT * FROM hr_letter_templates WHERE id=? AND company_id=?');mysqli_stmt_bind_param($stmt,'ii',$editId,$companyId);mysqli_stmt_execute($stmt);$edit=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt));mysqli_stmt_close($stmt);}
$list=mysqli_query($conn,'SELECT * FROM hr_letter_templates WHERE company_id='.(int)$companyId.' ORDER BY status DESC,letter_type,name');$flash=$_SESSION['letter_flash']??'';unset($_SESSION['letter_flash']);$presets=oecrm_letter_presets();
?>
<div id="page-wrapper" class="compact-admin-page letter-admin-page"><?php if($flash):?><div class="alert alert-success"><?php echo oecrm_h($flash);?></div><?php endif;?>
<div class="letter-layout"><div class="panel panel-default"><div class="panel-heading"><?php echo $edit?'Edit':'New';?> Letter Template</div><div class="panel-body">
<form method="post" action="hrLetterAction.php" class="letter-form"><?php echo oecrm_csrf_field();?><input type="hidden" name="action" value="save_template"><input type="hidden" name="id" value="<?php echo (int)($edit['id']??0);?>">
<div class="letter-form-grid"><div class="form-group"><label>Letter Type</label><select id="templateLetterType" name="letter_type" class="form-control" required><?php foreach(oecrm_letter_types() as $key=>$label):?><option value="<?php echo $key;?>" <?php echo ($edit['letter_type']??'')===$key?'selected':'';?>><?php echo $label;?></option><?php endforeach;?></select></div><div class="form-group"><label>Template Name</label><input id="templateName" name="name" class="form-control" required value="<?php echo oecrm_h($edit['name']??'');?>"></div></div>
