<div class="token-help"><strong>Auto-fill tokens</strong><span>{{employee_name}}</span><span>{{employee_code}}</span><span>{{designation}}</span><span>{{joining_date}}</span><span>{{company_name}}</span><span>{{effective_date}}</span><span>{{new_designation}}</span><span>{{revised_salary}}</span><span>{{last_working_date}}</span><span>{{reason}}</span></div>
<label class="check-line"><input type="checkbox" name="is_default" <?php echo !empty($edit['is_default'])?'checked':'';?>> Default template for this type</label><label class="check-line"><input type="checkbox" name="status" <?php echo !isset($edit['status'])||$edit['status']?'checked':'';?>> Active</label><button class="btn btn-primary"><i class="fa fa-save"></i> Save Template</button>
</form></div></div>
<div class="panel panel-default"><div class="panel-heading">Reusable Templates</div><div class="panel-body table-responsive"><table class="table foundation-table"><thead><tr><th>Type</th><th>Name</th><th>Default</th><th>Status</th><th>Action</th></tr></thead><tbody><?php while($row=mysqli_fetch_assoc($list)):?><tr><td><?php echo oecrm_h(oecrm_letter_types()[$row['letter_type']]??$row['letter_type']);?></td><td><strong><?php echo oecrm_h($row['name']);?></strong><small><?php echo oecrm_h($row['subject']);?></small></td><td><?php echo $row['is_default']?'Yes':'No';?></td><td><span class="letter-status <?php echo $row['status']?'issued':'cancelled';?>"><?php echo $row['status']?'Active':'Inactive';?></span></td><td><a class="icon-action" href="hrLetterTemplates.php?edit=<?php echo (int)$row['id'];?>" title="Edit"><i class="fa fa-pencil"></i></a></td></tr><?php endwhile;?></tbody></table></div></div>
</div></div></div>
<script>
(function(){var presets=<?php echo json_encode($presets,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);?>,types=<?php echo json_encode(oecrm_letter_types(),JSON_UNESCAPED_UNICODE);?>,select=document.getElementById('templateLetterType'),name=document.getElementById('templateName'),subject=document.getElementById('templateSubject'),body=document.getElementById('templateBody'),editing=<?php echo $edit?'true':'false';?>;function fill(){var preset=presets[select.value];if(!preset)return;if(!editing||!name.value)name.value='Standard '+types[select.value];if(!editing||!subject.value)subject.value=preset.subject;if(!editing||!body.value)body.value=preset.body;editing=false;}select.addEventListener('change',fill);fill();}());
</script>
